do $g$ begin execute 'create temporary view feya_access_expected as  WITH filtered AS (
         SELECT v2.canonical_product_id,
            v2.product_slug,
            v2.product_title,
            v2.h1,
            v2.card_title,
            v2.source_listing_id,
            v2.matched_etsy_listing_id,
            v2.product_type,
            v2.final_product_type_v2,
            v2.part,
            v2.part_subtype,
            v2.material,
            v2.material_detail,
            v2.color,
            v2.context_primary,
            v2.context_secondary,
            v2.persona,
            v2.gender,
            v2.components,
            v2.page_goal,
            v2.keyword_id,
            v2.keyword,
            v2.keyword_norm,
            v2.keyword_axis,
            v2.keyword_pattern,
            v2.suggested_page_level,
            v2.evidence_count,
            v2.source_count,
            v2.has_metric_snapshot,
            v2.metric_status,
            v2.fit_status_v1,
            v2.fit_status_v2,
            v2.fit_score_pre_metric_v1,
            v2.fit_score_pre_metric_v2,
            v2.component_required_flag,
            v2.keyword_component_detected,
            v2.component_confirmed_flag,
            v2.material_only_match_flag,
            v2.supporting_only_flag,
            v2.too_broad_keyword_flag,
            v2.product_not_seo_target_flag,
            v2.compatibility_status_v2,
            v2.blocked_reason_v2,
            v2.fit_reason_v2,
            v2.recommended_next_action,
            v2.evaluated_at,
                CASE
                    WHEN v2.has_metric_snapshot THEN ''metric_validated''::text
                    WHEN (v2.metric_status = ''wait_for_metrics''::text) THEN ''wait_for_metrics''::text
                    ELSE ''seed_only_needs_validation''::text
                END AS metric_lane,
            GREATEST(1, cardinality(regexp_split_to_array(TRIM(BOTH FROM COALESCE(v2.keyword_norm, ''''::text)), ''\s+''::text))) AS keyword_word_count,
                CASE
                    WHEN ((v2.fit_status_v2 = ''image_alt_fit''::text) OR (v2.suggested_page_level = ''image_alt''::text)) THEN true
                    ELSE false
                END AS image_alt_like_flag
           FROM feya_v_kw_product_fit_candidates_v2 v2
          WHERE ((v2.fit_status_v2 = ''strong_fit''::text) AND (v2.compatibility_status_v2 = ''compatible_candidate''::text) AND (COALESCE(v2.too_broad_keyword_flag, false) = false) AND (COALESCE(v2.supporting_only_flag, false) = false) AND (COALESCE(v2.product_not_seo_target_flag, false) = false) AND (COALESCE(v2.component_confirmed_flag, false) = true) AND ((COALESCE(v2.component_required_flag, false) = false) OR (COALESCE(v2.component_confirmed_flag, false) = true)) AND (v2.blocked_reason_v2 IS NULL) AND (lower(((((COALESCE(v2.product_title, ''''::text) || '' ''::text) || COALESCE(v2.h1, ''''::text)) || '' ''::text) || COALESCE(v2.card_title, ''''::text))) !~ ''(digital download|ai try on|preview from your photo|photo \+ 5 sec video|photo \+ video|video preview|individual sizes|delivery for|shipping|service item|sampler|probnik)''::text))
        ), ranked AS (
         SELECT f.canonical_product_id,
            f.product_slug,
            f.product_title,
            f.h1,
            f.card_title,
            f.source_listing_id,
            f.matched_etsy_listing_id,
            f.product_type,
            f.final_product_type_v2,
            f.part,
            f.part_subtype,
            f.material,
            f.material_detail,
            f.color,
            f.context_primary,
            f.context_secondary,
            f.persona,
            f.gender,
            f.components,
            f.page_goal,
            f.keyword_id,
            f.keyword,
            f.keyword_norm,
            f.keyword_axis,
            f.keyword_pattern,
            f.suggested_page_level,
            f.evidence_count,
            f.source_count,
            f.has_metric_snapshot,
            f.metric_status,
            f.fit_status_v1,
            f.fit_status_v2,
            f.fit_score_pre_metric_v1,
            f.fit_score_pre_metric_v2,
            f.component_required_flag,
            f.keyword_component_detected,
            f.component_confirmed_flag,
            f.material_only_match_flag,
            f.supporting_only_flag,
            f.too_broad_keyword_flag,
            f.product_not_seo_target_flag,
            f.compatibility_status_v2,
            f.blocked_reason_v2,
            f.fit_reason_v2,
            f.recommended_next_action,
            f.evaluated_at,
            f.metric_lane,
            f.keyword_word_count,
            f.image_alt_like_flag,
            row_number() OVER (PARTITION BY f.canonical_product_id ORDER BY
                CASE f.metric_lane
                    WHEN ''metric_validated''::text THEN 1
                    WHEN ''wait_for_metrics''::text THEN 2
                    ELSE 3
                END, f.fit_score_pre_metric_v2 DESC NULLS LAST, f.component_confirmed_flag DESC, f.evidence_count DESC NULLS LAST, f.keyword_word_count DESC, f.too_broad_keyword_flag, f.image_alt_like_flag, f.keyword_norm) AS candidate_rank_for_product
           FROM filtered f
        ), role_applied AS (
         SELECT r.canonical_product_id,
            r.product_slug,
            r.product_title,
            r.h1,
            r.card_title,
            r.source_listing_id,
            r.matched_etsy_listing_id,
            r.product_type,
            r.final_product_type_v2,
            r.part,
            r.part_subtype,
            r.material,
            r.material_detail,
            r.color,
            r.context_primary,
            r.context_secondary,
            r.persona,
            r.gender,
            r.components,
            r.page_goal,
            r.keyword_id,
            r.keyword,
            r.keyword_norm,
            r.keyword_axis,
            r.keyword_pattern,
            r.suggested_page_level,
            r.evidence_count,
            r.source_count,
            r.has_metric_snapshot,
            r.metric_status,
            r.fit_status_v1,
            r.fit_status_v2,
            r.fit_score_pre_metric_v1,
            r.fit_score_pre_metric_v2,
            r.component_required_flag,
            r.keyword_component_detected,
            r.component_confirmed_flag,
            r.material_only_match_flag,
            r.supporting_only_flag,
            r.too_broad_keyword_flag,
            r.product_not_seo_target_flag,
            r.compatibility_status_v2,
            r.blocked_reason_v2,
            r.fit_reason_v2,
            r.recommended_next_action,
            r.evaluated_at,
            r.metric_lane,
            r.keyword_word_count,
            r.image_alt_like_flag,
            r.candidate_rank_for_product,
                CASE
                    WHEN (r.candidate_rank_for_product = 1) THEN ''primary_candidate''::text
                    WHEN ((r.candidate_rank_for_product >= 2) AND (r.candidate_rank_for_product <= 5)) THEN ''secondary_candidate''::text
                    WHEN ((r.candidate_rank_for_product >= 6) AND (r.candidate_rank_for_product <= 10)) THEN ''semantic_support_candidate''::text
                    ELSE ''overflow_not_for_insert_yet''::text
                END AS recommended_keyword_role
           FROM ranked r
        ), eligibility AS (
         SELECT ra.canonical_product_id,
            ra.product_slug,
            ra.product_title,
            ra.h1,
            ra.card_title,
            ra.source_listing_id,
            ra.matched_etsy_listing_id,
            ra.product_type,
            ra.final_product_type_v2,
            ra.part,
            ra.part_subtype,
            ra.material,
            ra.material_detail,
            ra.color,
            ra.context_primary,
            ra.context_secondary,
            ra.persona,
            ra.gender,
            ra.components,
            ra.page_goal,
            ra.keyword_id,
            ra.keyword,
            ra.keyword_norm,
            ra.keyword_axis,
            ra.keyword_pattern,
            ra.suggested_page_level,
            ra.evidence_count,
            ra.source_count,
            ra.has_metric_snapshot,
            ra.metric_status,
            ra.fit_status_v1,
            ra.fit_status_v2,
            ra.fit_score_pre_metric_v1,
            ra.fit_score_pre_metric_v2,
            ra.component_required_flag,
            ra.keyword_component_detected,
            ra.component_confirmed_flag,
            ra.material_only_match_flag,
            ra.supporting_only_flag,
            ra.too_broad_keyword_flag,
            ra.product_not_seo_target_flag,
            ra.compatibility_status_v2,
            ra.blocked_reason_v2,
            ra.fit_reason_v2,
            ra.recommended_next_action,
            ra.evaluated_at,
            ra.metric_lane,
            ra.keyword_word_count,
            ra.image_alt_like_flag,
            ra.candidate_rank_for_product,
            ra.recommended_keyword_role,
            ((ra.candidate_rank_for_product <= 10) AND (ra.recommended_keyword_role = ANY (ARRAY[''primary_candidate''::text, ''secondary_candidate''::text, ''semantic_support_candidate''::text]))) AS insert_eligible_flag
           FROM role_applied ra
        ), product_readiness AS (
         SELECT eligibility.canonical_product_id,
            (count(*) FILTER (WHERE eligibility.insert_eligible_flag))::integer AS insert_eligible_count,
            (count(*) FILTER (WHERE (eligibility.insert_eligible_flag AND (eligibility.recommended_keyword_role = ''primary_candidate''::text))))::integer AS primary_candidate_count,
            (count(*) FILTER (WHERE (eligibility.insert_eligible_flag AND (eligibility.recommended_keyword_role = ''primary_candidate''::text) AND (eligibility.metric_lane = ''metric_validated''::text))))::integer AS metric_validated_primary_count,
            (count(*) FILTER (WHERE (eligibility.insert_eligible_flag AND (eligibility.metric_lane = ''metric_validated''::text))))::integer AS metric_validated_count,
            (count(*) FILTER (WHERE (eligibility.insert_eligible_flag AND (eligibility.metric_lane = ''wait_for_metrics''::text))))::integer AS wait_for_metrics_count,
            (count(*) FILTER (WHERE (eligibility.insert_eligible_flag AND (eligibility.metric_lane = ''seed_only_needs_validation''::text))))::integer AS seed_only_count
           FROM eligibility
          GROUP BY eligibility.canonical_product_id
        )
 SELECT e.canonical_product_id,
    e.matched_etsy_listing_id,
    e.product_slug,
    e.product_title,
    e.h1,
    e.card_title,
    e.product_type,
    e.final_product_type_v2,
    e.part AS final_primary_part,
    e.part,
    e.material,
    e.material_detail,
    e.color,
    e.context_primary,
    e.context_secondary,
    e.persona,
    e.gender,
    e.keyword_id,
    e.keyword,
    e.keyword_norm,
    e.keyword_axis,
    e.keyword_pattern,
    e.suggested_page_level,
    e.metric_status,
    e.metric_lane,
    e.has_metric_snapshot,
    e.evidence_count,
    e.source_count,
    e.fit_status_v2,
    e.compatibility_status_v2,
    e.fit_score_pre_metric_v2,
    e.keyword_word_count,
    e.candidate_rank_for_product,
    e.recommended_keyword_role,
    e.insert_eligible_flag,
        CASE
            WHEN (COALESCE(pr.insert_eligible_count, 0) = 0) THEN ''not_ready''::text
            WHEN (COALESCE(pr.insert_eligible_count, 0) < 3) THEN ''needs_more_keywords''::text
            WHEN (COALESCE(pr.metric_validated_primary_count, 0) >= 1) THEN ''ready_for_metric_validated_draft''::text
            WHEN ((COALESCE(pr.wait_for_metrics_count, 0) >= 1) AND (COALESCE(pr.metric_validated_count, 0) = 0)) THEN ''ready_for_wait_metrics_draft''::text
            ELSE ''needs_more_keywords''::text
        END AS seo_pack_readiness_status,
    e.component_required_flag,
    e.keyword_component_detected,
