 HAVING (count(*) > 0);'; execute 'create temporary view feya_access_actual as '||pg_get_viewdef('public.feya_v_metric_next_action_v1'::regclass); if pg_get_viewdef('pg_temp.feya_access_expected'::regclass) is distinct from pg_get_viewdef('pg_temp.feya_access_actual'::regclass) then raise exception 'Access definition drift: feya_v_metric_next_action_v1'; end if; drop view pg_temp.feya_access_expected; drop view pg_temp.feya_access_actual; end $g$;

